from taf.ul.ettf.logger import custom_logger


logger = custom_logger('TestableLibrary')


class BaseError(Exception):
    def __init__(self, cause, message):
        self.cause = cause
        self.msg = message
        super(BaseError, self).__init__(self._format_message())

    def _format_message(self):
        message = '\n\n' \
                  '--------------------------------- | ERROR | ----------------------------------\n\n' \
                  '| Type:    {}\n' \
                  '| Cause:   {}\n' \
                  '| Message: {}\n\n' \
                  '--------------------------------- | ERROR | ----------------------------------\n\n' \
                  ''.format(self.__class__.__name__, self.cause, self.msg)
        logger.error(self.cause)
        return message


class FunctionalError(BaseError):
    pass


class LibraryError(BaseError):
    pass
